body{
  margin:0;
  font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
  color:var(--text);
  background:linear-gradient(180deg,#ffffff 0%, var(--bg) 40%, var(--bg) 100%);
}

a{color:inherit}

.skip-link{
  position:absolute;left:-999px;top:12px;
  background:var(--surface);
  padding:10px 12px;
  border:1px solid var(--border);
  border-radius:10px;
  box-shadow:var(--shadow);
  z-index:2000;
}
.skip-link:focus{left:12px;outline:none;box-shadow:var(--shadow),var(--ring)}

.container{max-width:1240px;margin:0 auto;padding:0 var(--space-6)}

.app-header{
  position:sticky;top:0;z-index:1000;
  background:rgba(255,255,255,.78);
  backdrop-filter:saturate(140%) blur(10px);
  border-bottom:1px solid var(--border);
}

.nav-row{
  display:flex;align-items:center;justify-content:space-between;
  gap:var(--space-6);
  padding:var(--space-5) 0 var(--space-3);
}

.brand{display:flex;align-items:center;gap:var(--space-3);min-width:240px}
.brand-mark{
  width:40px;height:40px;border-radius:12px;
  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,.9) 0, rgba(255,255,255,0) 45%),
              linear-gradient(135deg, #3861fb 0%, #2246d8 50%, #0d1421 120%);
  box-shadow:0 10px 24px rgba(56,97,251,.22);
}
.brand-name{font-weight:700;letter-spacing:-.02em;line-height:1.1}
.brand-pro{color:var(--blue)}
.brand-sub{font-size:var(--fs-12);color:var(--muted);margin-top:2px}

.top-nav{flex:1}
.nav-toggle{display:none}

.nav-links{display:flex;gap:var(--space-4);align-items:center;justify-content:center;flex-wrap:wrap}
.nav-link{
  font-size:var(--fs-14);
  padding:10px 12px;
  border-radius:12px;
  color:var(--muted);
  text-decoration:none;
  border:1px solid transparent;
}
.nav-link:hover{background:rgba(56,97,251,.06);color:var(--text)}
.nav-link:focus-visible{outline:none;box-shadow:var(--ring)}
.nav-link.is-active{color:var(--text);background:rgba(56,97,251,.08);border-color:rgba(56,97,251,.14)}

.nav-cta{display:flex;gap:var(--space-2);align-items:center}

.btn{
  height:40px;
  padding:0 14px;
  border-radius:12px;
  border:1px solid var(--border);
  background:var(--surface);
  color:var(--text);
  font-weight:600;
  font-size:var(--fs-14);
  cursor:pointer;
  transition:transform .08s ease, background .15s ease, border-color .15s ease, box-shadow .15s ease;
}
.btn:hover{background:rgba(13,20,33,.03)}
.btn:active{transform:translateY(1px)}
.btn:focus-visible{outline:none;box-shadow:var(--ring)}

.btn-primary{background:var(--blue);border-color:rgba(56,97,251,.7);color:#fff;box-shadow:0 10px 22px rgba(56,97,251,.18)}
.btn-primary:hover{background:#2f56f6}

.btn-ghost{background:transparent;border-color:transparent;color:var(--muted)}
.btn-ghost:hover{background:rgba(13,20,33,.04);border-color:rgba(13,20,33,.06);color:var(--text)}

.btn-soft{background:var(--surface-2);border-color:rgba(13,20,33,.06)}
.btn-soft:hover{background:#eaf0ff;border-color:rgba(56,97,251,.18)}

.btn-caret{margin-left:8px;color:var(--muted)}

.stats-bar{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:var(--space-3);
  padding:0 0 var(--space-5);
}

.stat{
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:16px;
  padding:var(--space-4);
  box-shadow:0 1px 0 rgba(13,20,33,.03);
}
.stat-label{font-size:var(--fs-12);color:var(--muted);letter-spacing:.02em;text-transform:uppercase}
.stat-value{display:flex;align-items:baseline;gap:10px;margin-top:8px;font-weight:700}

.chip{
  display:inline-flex;align-items:center;gap:6px;
  height:24px;padding:0 10px;border-radius:999px;
  font-size:var(--fs-12);font-weight:700;
  border:1px solid transparent;
}
.chip-pos{color:var(--green);background:rgba(22,199,132,.10);border-color:rgba(22,199,132,.18)}
.chip-neg{color:var(--red);background:rgba(234,57,67,.10);border-color:rgba(234,57,67,.18)}
.chip-neutral{color:var(--muted);background:rgba(128,138,157,.12);border-color:rgba(128,138,157,.18)}

.chip-btn{cursor:pointer}
.chip-btn:hover{background:rgba(56,97,251,.10);border-color:rgba(56,97,251,.18);color:var(--text)}
.chip-btn:focus-visible{outline:none;box-shadow:var(--ring)}

.app-main{padding:var(--space-7) 0 var(--space-8)}

.promo{
  display:grid;
  grid-template-columns:40px 1fr 40px;
  gap:var(--space-3);
  align-items:center;
  margin-bottom:var(--space-5);
}

.promo-viewport{
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:var(--radius-lg);
  overflow:hidden;
  box-shadow:var(--shadow);
}

.promo-track{display:flex;transition:transform 300ms ease;will-change:transform}
.promo-slide{min-width:100%;padding:var(--space-5) var(--space-6);display:flex;align-items:center;justify-content:space-between;gap:var(--space-5)}
.promo-kicker{font-size:var(--fs-12);color:var(--muted);text-transform:uppercase;letter-spacing:.06em}
.promo-title{font-size:var(--fs-18);font-weight:800;letter-spacing:-.02em;margin-top:6px}
.promo-meta{font-size:var(--fs-13);color:var(--muted);margin-top:8px;line-height:1.5}
.promo-cta{display:flex;gap:var(--space-2);align-items:center}

.promo-arrow{
  width:40px;height:40px;border-radius:14px;
  border:1px solid var(--border);
  background:var(--surface);
  cursor:pointer;
  box-shadow:0 1px 0 rgba(13,20,33,.03);
  font-size:22px;line-height:1;color:var(--muted);
}
.promo-arrow:hover{background:rgba(56,97,251,.06);border-color:rgba(56,97,251,.20);color:var(--text)}
.promo-arrow:focus-visible{outline:none;box-shadow:var(--ring)}

.promo-dots{grid-column:1 / -1;display:flex;justify-content:center;gap:8px;margin-top:-8px}
.promo-dot{width:7px;height:7px;border-radius:999px;background:rgba(128,138,157,.35);border:1px solid rgba(128,138,157,.35);cursor:pointer}
.promo-dot.is-active{background:rgba(56,97,251,.75);border-color:rgba(56,97,251,.75)}
.promo-dot:focus-visible{outline:none;box-shadow:var(--ring)}

.ai-bar{
  display:flex;gap:var(--space-5);align-items:flex-start;justify-content:space-between;
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:var(--radius-lg);
  padding:var(--space-5) var(--space-6);
  box-shadow:0 1px 0 rgba(13,20,33,.03);
  margin-bottom:var(--space-6);
}

.ai-left{display:flex;gap:var(--space-4);align-items:center;min-width:320px}
.ai-pill{
  width:44px;height:44px;border-radius:14px;
  display:grid;place-items:center;
  background:rgba(56,97,251,.12);
  border:1px solid rgba(56,97,251,.22);
  color:var(--blue);
  font-weight:800;
}
.ai-title{font-weight:800;letter-spacing:-.01em}
.ai-prompt{color:var(--muted);font-size:var(--fs-14);margin-top:2px}

.ai-actions{display:flex;flex-wrap:wrap;gap:10px;justify-content:flex-end}

.filters{display:flex;flex-direction:column;gap:var(--space-3);margin-bottom:var(--space-6)}

.tabs{display:flex;gap:10px;flex-wrap:wrap}
.tab{
  height:36px;
  padding:0 12px;
  border-radius:999px;
  border:1px solid rgba(13,20,33,.08);
  background:rgba(255,255,255,.7);
  color:var(--muted);
  font-weight:700;
  font-size:var(--fs-13);
  cursor:pointer;
}
.tab:hover{background:rgba(56,97,251,.06);border-color:rgba(56,97,251,.18);color:var(--text)}
.tab:focus-visible{outline:none;box-shadow:var(--ring)}
.tab.is-active{background:rgba(56,97,251,.10);border-color:rgba(56,97,251,.22);color:var(--text)}

.tabs-secondary .tab{background:transparent}

.table-card{
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:var(--radius-lg);
  box-shadow:var(--shadow);
  overflow:hidden;
}

.table-head{
  display:flex;align-items:flex-end;justify-content:space-between;
  gap:var(--space-6);
  padding:var(--space-6);
  border-bottom:1px solid var(--border);
}
.table-title h1{font-size:var(--fs-24);margin:0;letter-spacing:-.03em}
.table-sub{color:var(--muted);margin-top:6px;font-size:var(--fs-13)}

.table-controls{display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end;align-items:center}
.control-group{position:relative}
.menu{
  position:absolute;right:0;top:calc(100% + 8px);
  width:220px;
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:14px;
  box-shadow:var(--shadow);
  padding:8px;
  z-index:100;
}
.menu-item{
  width:100%;text-align:left;
  border:1px solid transparent;
  border-radius:12px;
  background:transparent;
  padding:10px 10px;
  font-weight:700;
  font-size:var(--fs-13);
  color:var(--text);
  cursor:pointer;
}
.menu-item:hover{background:rgba(56,97,251,.08);border-color:rgba(56,97,251,.14)}
.menu-item:focus-visible{outline:none;box-shadow:var(--ring)}

.panels{padding:0 var(--space-6)}
.panel{
  margin:var(--space-4) 0;
  border:1px solid var(--border);
  background:linear-gradient(180deg, rgba(56,97,251,.04), rgba(56,97,251,0));
  border-radius:var(--radius-md);
  padding:var(--space-5);
}
.panel-grid{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:var(--space-4);
}
.field label{display:block;font-size:var(--fs-12);color:var(--muted);font-weight:700;letter-spacing:.02em;text-transform:uppercase;margin-bottom:8px}
.field input{
  width:100%;height:42px;
  border-radius:12px;
  border:1px solid rgba(13,20,33,.10);
  padding:0 12px;
  background:rgba(255,255,255,.85);
  font-size:var(--fs-14);
  font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}
.field input:focus{outline:none;box-shadow:var(--ring);border-color:rgba(56,97,251,.45);background:#fff}

.checkbox{display:flex;align-items:center;gap:10px;font-size:var(--fs-14);color:var(--text);font-weight:600}
.checkbox input{width:18px;height:18px}

.panel-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:var(--space-4)}
.columns-grid{grid-template-columns:repeat(5,minmax(0,1fr))}

.index-row{
  display:flex;justify-content:space-between;align-items:center;
  gap:var(--space-5);
  padding:var(--space-5) var(--space-6);
  border-top:1px solid var(--border);
  border-bottom:1px solid var(--border);
  background:linear-gradient(90deg, rgba(56,97,251,.08), rgba(56,97,251,0) 55%);
}
.index-left{display:flex;align-items:center;gap:var(--space-3)}
.index-badge{font-size:var(--fs-12);font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:var(--blue);background:rgba(56,97,251,.12);border:1px solid rgba(56,97,251,.22);padding:6px 10px;border-radius:999px}
.index-name{font-weight:800}
.index-sub{font-size:var(--fs-12);color:var(--muted);margin-top:4px}

.index-right{display:flex;gap:var(--space-5);flex-wrap:wrap;justify-content:flex-end}
.kv{min-width:110px}
.k{font-size:var(--fs-12);color:var(--muted);text-transform:uppercase;letter-spacing:.06em;font-weight:800}
.v{margin-top:6px;font-weight:900}

.table-wrap{overflow:auto;max-width:100%}
.data-table{width:100%;border-collapse:separate;border-spacing:0}
.data-table thead th{
  position:sticky;top:0;z-index:2;
  background:var(--surface);
  border-bottom:1px solid var(--border);
  font-size:var(--fs-12);
  color:var(--muted);
  text-transform:uppercase;
  letter-spacing:.06em;
  font-weight:900;
  padding:14px 12px;
  white-space:nowrap;
}
.data-table thead th[data-sort-key]{cursor:pointer}
.data-table thead th[data-sort-key]:hover{color:var(--text)}
.data-table tbody td{
  border-bottom:1px solid rgba(230,234,242,.9);
  padding:14px 12px;
  font-size:var(--fs-14);
  vertical-align:middle;
  white-space:nowrap;
}
.data-table tbody tr:hover{background:rgba(56,97,251,.04)}

.num{text-align:right}
.mono{font-family:var(--mono);font-variant-numeric:tabular-nums; font-feature-settings:"tnum" 1, "ss01" 1}
.pos{color:var(--green)}
.neg{color:var(--red)}
.muted{color:var(--muted)}

.asset{
  display:flex;align-items:center;gap:12px;min-width:260px;
}
.icon{
  width:28px;height:28px;border-radius:10px;
  display:grid;place-items:center;
  border:1px solid rgba(13,20,33,.10);
  background:linear-gradient(180deg,#fff, #f3f6ff);
  color:var(--text);
  font-weight:900;
  font-size:12px;
}
.asset-meta{line-height:1.15}
.asset-name{font-weight:800}
.asset-sym{font-size:var(--fs-12);color:var(--muted);margin-top:4px}

.spark{width:120px;height:32px}

.table-foot{
  display:flex;align-items:center;justify-content:space-between;
  gap:var(--space-4);
  padding:var(--space-5) var(--space-6);
}
.foot-left{color:var(--muted);font-size:var(--fs-13)}

.pager{display:flex;gap:6px;align-items:center;flex-wrap:wrap;justify-content:flex-end}
.page-btn{
  height:34px;min-width:34px;
  padding:0 10px;
  border-radius:12px;
  border:1px solid rgba(13,20,33,.10);
  background:rgba(255,255,255,.7);
  color:var(--text);
  font-weight:800;
  font-size:var(--fs-13);
  cursor:pointer;
}
.page-btn:hover{background:rgba(56,97,251,.06);border-color:rgba(56,97,251,.18)}
.page-btn:focus-visible{outline:none;box-shadow:var(--ring)}
.page-btn.is-active{background:rgba(56,97,251,.12);border-color:rgba(56,97,251,.25)}
.page-ellipsis{padding:0 8px;color:var(--muted);font-weight:800}

.summary{
  margin-top:var(--space-6);
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:var(--radius-lg);
  padding:var(--space-6);
  box-shadow:0 1px 0 rgba(13,20,33,.03);
}
.summary-head{display:flex;align-items:center;justify-content:space-between;gap:var(--space-4)}
.summary h2{margin:0;font-size:var(--fs-20);letter-spacing:-.02em}
.summary-text{margin:12px 0 0;color:var(--muted);line-height:1.7}

.link-btn{
  border:none;background:transparent;color:var(--blue);
  font-weight:800;cursor:pointer;padding:8px 10px;border-radius:10px
}
.link-btn:hover{background:rgba(56,97,251,.08)}
.link-btn:focus-visible{outline:none;box-shadow:var(--ring)}

.info{margin-top:var(--space-6)}
.info-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--space-4)}
.info-card{
  background:var(--surface);
  border:1px solid var(--border);
  border-radius:var(--radius-lg);
  padding:var(--space-6);
  box-shadow:0 1px 0 rgba(13,20,33,.03);
}
.info-card h3{margin:0 0 10px;font-size:var(--fs-16);letter-spacing:-.01em}
.info-card p{margin:0;color:var(--muted);line-height:1.7}

.footer{margin-top:var(--space-7);padding:var(--space-7) 0 var(--space-5);border-top:1px solid var(--border)}
.footer-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--space-6)}
.footer-title{font-weight:900;letter-spacing:.06em;text-transform:uppercase;font-size:var(--fs-12);color:var(--muted);margin-bottom:12px}
.footer-link{display:block;text-decoration:none;color:var(--text);padding:8px 0;font-weight:600}
.footer-link:hover{color:var(--blue)}
.footer-link:focus-visible{outline:none;box-shadow:var(--ring);border-radius:10px}
.footer-bottom{margin-top:var(--space-6);color:var(--muted);font-size:var(--fs-13)}

/* Column visibility (controlled by JS toggles) */
.hide-col-rank .col-rank, .hide-col-rank td.col-rank{display:none}
.hide-col-name .col-name, .hide-col-name td.col-name{display:none}
.hide-col-price .col-price, .hide-col-price td.col-price{display:none}
.hide-col-1h .col-1h, .hide-col-1h td.col-1h{display:none}
.hide-col-24h .col-24h, .hide-col-24h td.col-24h{display:none}
.hide-col-7d .col-7d, .hide-col-7d td.col-7d{display:none}
.hide-col-mcap .col-mcap, .hide-col-mcap td.col-mcap{display:none}
.hide-col-vol .col-vol, .hide-col-vol td.col-vol{display:none}
.hide-col-supply .col-supply, .hide-col-supply td.col-supply{display:none}
.hide-col-spark .col-spark, .hide-col-spark td.col-spark{display:none}

/* Responsive */
@media (max-width: 1100px){
  .container{padding:0 var(--space-5)}
  .stats-bar{grid-template-columns:repeat(2,minmax(0,1fr))}
  .panel-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .columns-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .info-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}

@media (max-width: 860px){
  .nav-row{align-items:flex-start}
  .brand{min-width:auto}
  .top-nav{order:3;flex-basis:100%}
  .nav-toggle{display:inline-flex;align-items:center;justify-content:center}
  .nav-links{display:none;justify-content:flex-start;padding-top:10px}
  .top-nav[data-open="true"] .nav-links{display:flex}
  .ai-bar{flex-direction:column;align-items:stretch}
  .ai-actions{justify-content:flex-start}
  .table-head{flex-direction:column;align-items:flex-start}
  .table-controls{justify-content:flex-start}
  .index-row{flex-direction:column;align-items:flex-start}
  .index-right{justify-content:flex-start}
  .footer-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}

@media (max-width: 520px){
  .container{padding:0 var(--space-4)}
  .promo{grid-template-columns:36px 1fr 36px}
  .promo-slide{padding:var(--space-5) var(--space-5)}
  .info-grid{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
}

@media (prefers-reduced-motion: reduce){
  .promo-track{transition:none}
  *{scroll-behavior:auto}
}
EOF"}

