    STATE.sortKey = item.dataset.sort;
    STATE.sortDir = item.dataset.dir;
    btn.querySelector('.btn-label').textContent = item.textContent.trim();
    STATE.page = 1;
    renderAll();
    hideSortMenu();
  });
}

