    const key = th.getAttribute('data-sort-key');
    if (STATE.sortKey === key){
      STATE.sortDir = STATE.sortDir === 'desc' ? 'asc' : 'desc';
    } else {
      STATE.sortKey = key;
      STATE.sortDir = (key === 'name' || key === 'rank') ? 'asc' : 'desc';
    }

